for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{outp}'")
    print("Position: ", end="")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            print(f"{j:2}", end=" ")
        elif j < len(inp):
            print(f"{j:2}", end=" ")
        else:
            print("  ", end=" ")
    print()

    print("Input:   ", end="")
    for j in range(len(inp)):
        print(f"{inp[j]:2}", end=" ")
    print()

    print("Output:  ", end="")
    for j in range(len(outp)):
        print(f"{outp[j]:2}", end=" ")
    print()

    # Let me see the actual differences
    print("Diff:    ", end="")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            if inp[j] == outp[j]:
                print("  ", end=" ")
            else:
                print("↑", end=" ")
        elif j < len(inp):
            print("↓", end=" ")
        else:
            print("↑", end=" ")
    print()

